/* =========================================================
   PDF DA ORDEM DE SERVIÇO - MIMETIC SOFT
   Gera o documento diretamente no navegador, sem servidor.
   BACKEND: futuramente o PDF também poderá ser gerado pela API.
   ========================================================= */
   //USER: Matheus Lino
(() => {
  // Lê o valor de um campo do formulário pelo id (sem espaços nas pontas).
  const get = id => document.getElementById(id)?.value?.trim() || '';
  // Novo logotipo MIMETIC SOFT preservando a transparência original no PDF.
  const LOGO_RGB_FLATE_BASE64 = '';
  const LOGO_ALPHA_FLATE_BASE64 = '';
  const LOGO_PDF_WIDTH = 300;
  const LOGO_PDF_HEIGHT = 257;

  // Converte uma data AAAA-MM-DD para DD/MM/AAAA; sem data devolve "A definir".
  //USER: Matheus Lino
  function dataBR(valor) {
    if (!valor) return 'A definir';
    const [a,m,d] = valor.split('-');
    return a && m && d ? `${d}/${m}/${a}` : valor;
  }
  // Devolve a data de hoje no formato DD/MM/AAAA.
  //USER: Matheus Lino
  function hojeBR() { return new Date().toLocaleDateString('pt-BR'); }
  // Troca caracteres que a fonte padrão do PDF não suporta (travessões, aspas curvas, etc.) por equivalentes simples.
  //USER: Matheus Lino
  function latin1(texto) {
    return String(texto ?? '')
      .replace(/[–—]/g, '-').replace(/[“”]/g, '"').replace(/[‘’]/g, "'")
      .replace(/€/g, 'EUR').replace(/…/g, '...');
  }
  // Prepara um texto para entrar no PDF, escapando barra invertida e parênteses (caracteres especiais do formato PDF).
  //USER: Matheus Lino
  function esc(texto) { return latin1(texto).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)'); }
  // Quebra um texto longo em várias linhas de no máximo "max" caracteres, sem cortar palavras.
  //USER: Matheus Lino
  function wrap(texto, max=78) {
    const palavras=latin1(texto).split(/\s+/); const linhas=[]; let atual='';
    palavras.forEach(p=>{ const teste=(atual+' '+p).trim(); if(teste.length>max && atual){linhas.push(atual);atual=p;}else atual=teste; });
    if(atual) linhas.push(atual); return linhas.length?linhas:['-'];
  }
  // Converte um texto em bytes (Latin-1), formato exigido para montar o arquivo PDF.
  //USER: Matheus Lino
  function bytesLatin1(str) { const out=new Uint8Array(str.length); for(let i=0;i<str.length;i++) out[i]=str.charCodeAt(i)&255; return out; }

  // Monta o arquivo PDF (A4) da ordem de serviço a partir dos dados "d" e devolve um Blob para download.
  //USER: Matheus Lino
  function criarPdf(d) {
    // PDF A4 simples, com identidade visual MIMETIC SOFT (vermelho, cinza e verde).
    const ops=[];
    // Auxiliares de desenho: txt escreve um texto na posição (x,y); line traça uma linha; fill pinta um retângulo.
    const txt=(x,y,size,text,bold=false,rgb='0.20 0.20 0.20')=>ops.push(`BT /${bold?'F2':'F1'} ${size} Tf ${rgb} rg ${x} ${y} Td (${esc(text)}) Tj ET`);
    const line=(x1,y1,x2,y2,rgb='0.85 0.85 0.85')=>ops.push(`${rgb} RG 1 w ${x1} ${y1} m ${x2} ${y2} l S`);
    const fill=(x,y,w,h,rgb)=>ops.push(`${rgb} rg ${x} ${y} ${w} ${h} re f`);
    fill(0,792,595,50,'1 0.275 0.298');
    // Logotipo no cabeçalho do PDF, dimensionado para caber sem deformar.
    ops.push('q 47 0 0 40 36 797 cm /Im1 Do Q');
    txt(88,810,22,'MIMETIC SOFT',true,'1 1 1');
    txt(42,765,18,'ORDEM DE SERVIÇO / ORÇAMENTO',true,'1 0.275 0.298');
    txt(430,766,9,`Emitido em ${d.emissao}`,false,'0.45 0.45 0.45');
    line(42,752,553,752,'1 0.275 0.298');
    let y=728;
    // Seções em estilo zebrado: lembram uma tabela, mas sem grades ou colunas rígidas.
    // Isso aproxima rótulo e informação e melhora a leitura do documento.
    // Desenha o título de uma seção (faixa cinza) e desce a posição vertical.
    const sec=(titulo)=>{
      fill(42,y-4,511,24,'0.94 0.94 0.94');
      txt(52,y+4,11,titulo,true,'1 0.275 0.298');
      y-=31;
    };
    let zebra=0;
    // Desenha uma linha "rótulo: valor" com fundo alternado (zebrado) e desce a posição vertical.
    const row=(label,value)=>{
      const fundo = zebra % 2 === 0 ? '0.965 0.965 0.965' : '0.992 0.992 0.992';
      fill(52,y-7,491,24,fundo);
      txt(62,y,9,label,true,'0.34 0.34 0.34');
      txt(178,y,9.5,value||'-',false,'0.18 0.18 0.18');
      y-=24;
      zebra++;
    };
    sec('DADOS DO CLIENTE');
    zebra=0;
    row('Nome:',d.nome); row('CPF:',d.cpf); row('Telefone:',d.telefone); row('E-mail:',d.email);
    y-=9;
    sec('VEÍCULO E SOLICITAÇÃO');
    zebra=0;
    row('Veículo:',d.veiculo); row('Ano do veículo:',d.anoCarro); row('Placa:',d.placa); row('Nº Chassi:',d.chassi||d.solicitacao);
    const itens=Array.isArray(d.servicos)?d.servicos:(d.servicos?[{nome:String(d.servicos),preco:d.orcamento||'0,00'}]:[]);
    const alturaServicos=Math.max(46,itens.length*18+30);
    fill(52,y-alturaServicos+17,491,alturaServicos,'0.975 0.975 0.975');
    txt(62,y,9,'SERVIÇOS REALIZADOS',true,'0.34 0.34 0.34'); txt(455,y,9,'PREÇO',true,'0.34 0.34 0.34');
    let sy=y-19;
    itens.slice(0,8).forEach((item,i)=>{txt(62,sy-(i*18),9.5,item.nome||'',false,'0.18 0.18 0.18');txt(455,sy-(i*18),9.5,`R$ ${item.preco||'0,00'}`,false,'0.18 0.18 0.18');});
    if(!itens.length) txt(62,sy,9.5,'Nenhum serviço informado',false,'0.45 0.45 0.45');
    y-=alturaServicos+25;
    // Espaço extra antes dos cards finais para evitar que encostem em "Serviços a realizar".
    fill(52,y-8,235,54,'1 0.98 0.98'); fill(305,y-8,238,54,'0.97 1 0.96');
    txt(64,y+24,9,'PREVISÃO DE CONCLUSÃO',true,'1 0.275 0.298'); txt(64,y+4,16,d.previsao,true);
    txt(317,y+24,9,'ORÇAMENTO',true,'0.25 0.55 0.20'); txt(317,y+4,18,`R$ ${d.orcamento}`,true,'1 0.275 0.298');
    y-=78;
    line(42,y,553,y); y-=22;
    txt(42,y,9,'Documento gerado pelo MIMETIC SOFT para apresentação dos serviços previstos.',false,'0.45 0.45 0.45');
    y-=16; txt(42,y,9,'Valores e prazos poderão ser atualizados pela oficina mediante comunicação ao cliente.',false,'0.45 0.45 0.45');
    y-=48; line(70,y,260,y); line(335,y,525,y);
    txt(112,y-15,9,'Responsável da oficina',false,'0.45 0.45 0.45'); txt(385,y-15,9,'Cliente',false,'0.45 0.45 0.45');

    const content=ops.join('\n');
    const objs=[];
    objs[1]='<< /Type /Catalog /Pages 2 0 R >>';
    objs[2]='<< /Type /Pages /Kids [3 0 R] /Count 1 >>';
    objs[3]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> /XObject << /Im1 7 0 R >> >> /Contents 6 0 R >>';
    objs[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
    objs[5]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
    objs[6]=`<< /Length ${bytesLatin1(content).length} >>\nstream\n${content}\nendstream`;
    // A imagem é derivada do PNG original. O /SMask mantém o canal alfa,
    // evitando o fundo preto e deixando o logo igual ao exibido nas telas.
    const logoRgbBin = atob(LOGO_RGB_FLATE_BASE64);
    const logoAlphaBin = atob(LOGO_ALPHA_FLATE_BASE64);
    objs[7]=`<< /Type /XObject /Subtype /Image /Width ${LOGO_PDF_WIDTH} /Height ${LOGO_PDF_HEIGHT} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode /SMask 8 0 R /Length ${logoRgbBin.length} >>\nstream\n${logoRgbBin}\nendstream`;
    objs[8]=`<< /Type /XObject /Subtype /Image /Width ${LOGO_PDF_WIDTH} /Height ${LOGO_PDF_HEIGHT} /ColorSpace /DeviceGray /BitsPerComponent 8 /Filter /FlateDecode /Length ${logoAlphaBin.length} >>\nstream\n${logoAlphaBin}\nendstream`;
    let pdf='%PDF-1.4\n%âãÏÓ\n', offsets=[0];
    for(let i=1;i<objs.length;i++){offsets[i]=bytesLatin1(pdf).length;pdf+=`${i} 0 obj\n${objs[i]}\nendobj\n`;}
    const xref=bytesLatin1(pdf).length;
    pdf+=`xref\n0 ${objs.length}\n0000000000 65535 f \n`;
    for(let i=1;i<objs.length;i++) pdf+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';
    pdf+=`trailer\n<< /Size ${objs.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
    return new Blob([bytesLatin1(pdf)],{type:'application/pdf'});
  }

  // Gera e baixa o PDF da ordem de serviço. Se receber uma ordem já salva, usa os dados dela;
  // sem argumento, usa o que está digitado no formulário da tela.
  //USER: Matheus Lino
  function gerarOrdemServico(ordemSalva) {
    // Pode gerar pela tela de cadastro ou por uma ordem já salva na lista.
    const o = ordemSalva && typeof ordemSalva === 'object' ? ordemSalva : null;
    const dados=o ? {
      nome:o.cliente||'', cpf:o.cpf||'', telefone:o.telefone||'', email:o.email||'',
      veiculo:o.veiculo||'', placa:String(o.placa||'').toUpperCase(), chassi:o.chassi||o.solicitacao||'', solicitacao:o.solicitacao||'', anoCarro:o.anoCarro||o.peca||'',
      servicos:o.servicos||[], previsao:dataBR(o.previsao||o.conclusao||''), orcamento:o.orcamento||'0,00', emissao:hojeBR()
    } : {
      nome:get('nome'),cpf:get('cpf'),telefone:get('telefone'),email:get('email'),
      veiculo:get('modelo'),placa:get('placa').toUpperCase(),chassi:get('solicitacao'),solicitacao:get('solicitacao'),anoCarro:get('ano-carro'),
      servicos:(window.MimeticServicos?.listar?.()||[]),previsao:dataBR(get('previsao-conclusao')),orcamento:get('orcamento')||'0,00',emissao:hojeBR()
    };
    const blob=criarPdf(dados); const url=URL.createObjectURL(blob); const a=document.createElement('a');
    a.href=url; a.download=`MIMETIC_SOFT_Ordem_${(dados.placa||'veiculo').replace(/[^A-Z0-9]/gi,'_')}.pdf`;
    document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),1500);
  }
  window.MimeticPDF={gerarOrdemServico};
})();
